contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logAddr) public payable {
        require(logAddr != address(0), "logAddr must be nonzero");

        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        bool firstReverted;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint afterFirstMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetLogFile(logAddr); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(!firstReverted && secondReverted && beforeMinSum == afterFirstMinSum);
    }

    receive() external payable {}
}

